            Ok(value) => numbers.push(value),
            Err(_) => return String::new(),
        }
    }
    let (major, minor, patch) = (numbers[0], numbers[1], numbers[2]);
    match part {
        "major" => format!("{}.0.{}", major + 1, patch),
        "minor" => format!("{}.{}.{}", major, minor + 1, patch),
        "patch" => format!("{}.{}.{}", major, minor, patch + 1),
        _ => String::new(),
    }
}

