    return int(text[:end]) * _UNITS[suffix]

const UNITS: Record<string, number> = {
    "": 1,
    K: 1024,
    Ki: 1024,
    M: 1048576,
    Mi: 1048576,
    G: 1073741824,
    Gi: 1073741824,
};

function parseSize(text: string): number {
    let end = 0;
    while (end < text.length && text[end] >= "0" && text[end] <= "9") end++;
    if (end === 0) return -1;
    const suffix = text.slice(end);
    if (!Object.prototype.hasOwnProperty.call(UNITS, suffix)) return -1;
    return parseInt(text.slice(0, end), 10) * UNITS[suffix];
}

import "strconv"

func ParseSize(text string) int {
    units := map[string]int{
        "":   1,
        "K":  1024,
        "Ki": 1024,
        "M":  1048576,
        "Mi": 1048576,
        "G":  1073741824,
        "Gi": 1073741824,
    }
    end := 0
    for end < len(text) && text[end] >= '0' && text[end] <= '9' {
        end++
    }
    if end == 0 {
        return -1
    }
    scale, ok := units[text[end:]]
    if !ok {
        return -1
    }
    value, err := strconv.Atoi(text[:end])
    if err != nil {
        return -1
    }
    return value * scale
}

fn parse_size(text: &str) -> i64 {
    let bytes = text.as_bytes();
    let mut end = 0usize;
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
    }
    if end == 0 {
        return -1;
    }
    let scale: i64 = match &text[end..] {
        "" => 1,
        "K" => 1024,
        "Ki" => 1024,
        "M" => 1048576,
        "Mi" => 1048576,
        "G" => 1073741824,
        "Gi" => 1073741824,
        _ => return -1,
    };
    match text[..end].parse::<i64>() {
        Ok(value) => value * scale,
        Err(_) => -1,
    }
}
